<style>
.calendar-panel{padding:clamp(14px,2.5vw,26px)}.calendar-toolbar{justify-content:space-between;margin-bottom:18px}.calendar-legend{display:flex;gap:18px;flex-wrap:wrap;font-size:12px;color:#526579;margin:12px 0 18px}.calendar-legend span{display:flex;align-items:center;gap:7px}.dot{width:9px;height:9px;border-radius:50%;display:inline-block}.dot.booked{background:#299fd3}.dot.closed{background:#e87932}.dot.override{background:#53a6a0}.calendar-grid{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));border-top:1px solid #dfe8ef;border-left:1px solid #dfe8ef}.cal-head,.cal-cell{border-right:1px solid #dfe8ef;border-bottom:1px solid #dfe8ef;min-width:0}.cal-head{padding:10px 4px;text-align:center;background:#f4f9fc;font-size:11px;font-weight:800;color:#50677a}.cal-cell{min-height:105px;padding:7px;background:#fff;cursor:pointer;transition:background .15s}.cal-cell:hover{background:#f1f9fd}.cal-cell.outside{background:#f8fafc;color:#a6b2bc}.cal-cell.today{box-shadow:inset 0 0 0 2px #37a9df}.cal-day{font-size:12px;font-weight:800;display:flex;justify-content:space-between}.cal-event{font-size:10px;line-height:1.35;padding:4px 5px;margin-top:5px;border-radius:5px;background:#e5f5fc;color:#165e7d;overflow:hidden;white-space:nowrap;text-overflow:ellipsis}.cal-event.closed{background:#fff0e4;color:#9a4c16}.cal-event.override{background:#e4f5f1;color:#226b61}.cal-more{font-size:10px;color:#526579;margin-top:4px}.calendar-modal[hidden]{display:none}.calendar-modal{position:fixed;inset:0;z-index:2000;background:#122b3b88;display:grid;place-items:center;padding:16px}.calendar-dialog{position:relative;background:white;color:#24394a;width:min(760px,100%);max-height:90vh;overflow:auto;border-radius:16px;padding:clamp(20px,4vw,34px);box-shadow:0 25px 90px #092b3a35;animation:modalIn .18s ease-out}.calendar-dialog h2{margin:0 40px 15px 0}.modal-close{position:absolute;right:16px;top:12px;border:0;background:#edf5f9;border-radius:50%;font-size:25px;width:38px;height:38px}.calendar-dialog label{display:block;font-size:12px;font-weight:700;margin:12px 0 5px}.calendar-dialog input:not([type=checkbox]){width:100%;padding:11px;border:1px solid #cbdce6;border-radius:8px}.calendar-dialog input[type=checkbox]{width:auto}.check-label{display:flex!important;align-items:center;gap:8px}.modal-actions{justify-content:flex-end;margin-top:22px}.day-booking{padding:11px 0;border-bottom:1px solid #e4edf2;display:flex;gap:10px;justify-content:space-between;flex-wrap:wrap}.day-booking strong{color:#236e91}.day-booking small{display:block;color:#687d8d}.calendar-toolbar button,.secondary{background:#edf6fa;border:1px solid #d4e6ef;border-radius:8px;padding:9px 12px;color:#28566f}.calendar-toolbar button:hover,.secondary:hover{background:#dff1f9}@keyframes modalIn{from{opacity:0;transform:translateY(8px) scale(.99)}to{opacity:1;transform:none}}@media(max-width:650px){.cal-cell{min-height:74px;padding:4px}.cal-event{font-size:9px;padding:3px}.cal-head{font-size:10px}.calendar-toolbar{align-items:flex-start;flex-direction:column}.cal-cell .cal-event:nth-of-type(n+2){display:none}}@media(prefers-reduced-motion:reduce){.calendar-dialog{animation:none}.cal-cell{transition:none}}
</style>
<script>
(()=> {
 const api=@json(route('admin.calendar.events')),dayApi=@json(route('admin.calendar.day')),grid=document.getElementById('calendar-grid'),title=document.getElementById('cal-title'),modal=document.getElementById('day-modal');
 let cursor=new Date(),mode='month',events=[];
 const days=['Lun','Mar','Mer','Jeu','Ven','Sam','Dim'],pad=n=>String(n).padStart(2,'0'),iso=d=>`${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`;
 function period(){let start=new Date(cursor);if(mode==='month'){start=new Date(cursor.getFullYear(),cursor.getMonth(),1);let wd=(start.getDay()+6)%7;start.setDate(start.getDate()-wd);let end=new Date(start);end.setDate(end.getDate()+41);return [start,end]}let wd=(start.getDay()+6)%7;start.setDate(start.getDate()-wd);let end=new Date(start);end.setDate(end.getDate()+7);return [start,end]}
 async function render(){const [start,end]=period();title.textContent=mode==='month'?cursor.toLocaleDateString('fr-FR',{month:'long',year:'numeric'}):`${start.toLocaleDateString('fr-FR',{day:'numeric',month:'short'})} – ${new Date(end-86400000).toLocaleDateString('fr-FR',{day:'numeric',month:'short',year:'numeric'})}`;grid.replaceChildren();days.forEach(d=>{let el=document.createElement('div');el.className='cal-head';el.textContent=d;grid.append(el)});try{let r=await fetch(`${api}?start=${iso(start)}&end=${iso(end)}`,{headers:{Accept:'application/json'}});if(!r.ok)throw Error();events=await r.json()}catch(e){grid.innerHTML='<p class="alert error">Impossible de charger l’agenda. Réessayez après actualisation.</p>';return}
 const today=iso(new Date());for(let i=0;i<(mode==='month'?42:7);i++){let d=new Date(start);d.setDate(start.getDate()+i);let date=iso(d),cell=document.createElement('button');cell.type='button';cell.className='cal-cell'+(mode==='month'&&d.getMonth()!==cursor.getMonth()?' outside':'')+(date===today?' today':'');cell.setAttribute('aria-label','Ouvrir le '+date);let day=document.createElement('div');day.className='cal-day';day.textContent=d.getDate();cell.append(day);let list=events.filter(e=>(e.start||'').slice(0,10)===date);list.slice(0,3).forEach(e=>{let chip=document.createElement('div');chip.className='cal-event '+(e.type==='closed'?'closed':e.type==='override'?'override':'');chip.textContent=e.title;cell.append(chip)});if(list.length>3){let more=document.createElement('div');more.className='cal-more';more.textContent=`+${list.length-3} autre(s)`;cell.append(more)}cell.addEventListener('click',()=>openDay(date));grid.append(cell)}}
 async function openDay(date){document.getElementById('day-date').value=date;document.getElementById('day-title').textContent=new Date(date+'T12:00:00').toLocaleDateString('fr-FR',{weekday:'long',day:'numeric',month:'long',year:'numeric'});document.getElementById('day-bookings').innerHTML='<p>Chargement des rendez-vous…</p>';modal.hidden=false;document.body.classList.add('modal-open');try{let r=await fetch(`${dayApi}?date=${date}`,{headers:{Accept:'application/json'}});if(!r.ok)throw Error();let d=await r.json(),wrap=document.getElementById('day-bookings');wrap.replaceChildren();if(!d.bookings.length){let p=document.createElement('p');p.className='muted';p.textContent='Aucun rendez-vous actif pour cette date.';wrap.append(p)}d.bookings.forEach(b=>{let row=document.createElement('div');row.className='day-booking';let info=document.createElement('div'),strong=document.createElement('strong');strong.textContent=`${b.time}${b.end?'–'+b.end:''} · ${b.customer}`;let small=document.createElement('small');small.textContent=`${b.service||'Prestation'} · ${b.status} · ${b.reference}`;info.append(strong,small);let a=document.createElement('a');a.href=@json(route('admin.bookings.index'));a.className='secondary';a.textContent='Gérer les rendez-vous';row.append(info,a);wrap.append(row)});document.getElementById('day-open').checked=!d.closed&&!!d.hours.is_open;document.getElementById('day-start').value=(d.hours.open_time||'09:00').slice(0,5);document.getElementById('day-end').value=(d.hours.close_time||'18:00').slice(0,5);let br=(d.hours.breaks||[])[0]||{};document.getElementById('break-start').value=br.start||'';document.getElementById('break-end').value=br.end||'';document.getElementById('day-label').value=d.override?.label||'';toggleHours()}catch(e){document.getElementById('day-bookings').textContent='Chargement impossible. Vérifiez votre connexion puis réessayez.'}}
 function toggleHours(){document.getElementById('day-hours').style.display=document.getElementById('day-open').checked?'grid':'none'}
 function close(){modal.hidden=true;document.body.classList.remove('modal-open')}
 document.getElementById('cal-prev').onclick=()=>{if(mode==='month')cursor=new Date(cursor.getFullYear(),cursor.getMonth()-1,1);else cursor.setDate(cursor.getDate()-7);render()};document.getElementById('cal-next').onclick=()=>{if(mode==='month')cursor=new Date(cursor.getFullYear(),cursor.getMonth()+1,1);else cursor.setDate(cursor.getDate()+7);render()};document.getElementById('cal-today').onclick=()=>{cursor=new Date();render()};document.getElementById('view-month').onclick=()=>{mode='month';render()};document.getElementById('view-week').onclick=()=>{mode='week';render()};document.getElementById('day-close').onclick=document.getElementById('day-cancel').onclick=close;modal.addEventListener('click',e=>{if(e.target===modal)close()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!modal.hidden)close()});document.getElementById('day-open').addEventListener('change',toggleHours);
 document.getElementById('day-form').addEventListener('submit',e=>{let s=document.getElementById('break-start').value,en=document.getElementById('break-end').value;document.querySelectorAll('#day-form input[name^="breaks"]').forEach(n=>n.remove());if(s&&en){[['start',s],['end',en]].forEach(([k,v])=>{let i=document.createElement('input');i.type='hidden';i.name=`breaks[0][${k}]`;i.value=v;e.target.append(i)})}else if(s||en){e.preventDefault();alert('Veuillez renseigner le début et la fin de la pause.')}});render();
})();
</script>
